<?php
require_once "config/db.php";$id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT * FROM members WHERE id=?");$st->execute([$id]);$member=$st->fetch();if(!$member){$_SESSION['flash']=['type'=>'error','message'=>'Member not found.'];header("Location: members.php");exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$gender=$_POST['gender']??'Prefer not to say';$join=$_POST['join_date']??date('Y-m-d');$plan=$_POST['plan_id']?:null;$status=$_POST['status']??'Active';if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/^[0-9]{10,15}$/',$phone)){$_SESSION['flash']=['type'=>'error','message'=>'Please enter valid details.'];}else{try{$st=$pdo->prepare("UPDATE members SET name=?,email=?,phone=?,gender=?,join_date=?,plan_id=?,status=? WHERE id=?");$st->execute([$name,$email,$phone,$gender,$join,$plan,$status,$id]);$_SESSION['flash']=['type'=>'success','message'=>'Member updated.'];header("Location: members.php");exit;}catch(PDOException $e){$_SESSION['flash']=['type'=>'error','message'=>'That email is already used.'];}}$st=$pdo->prepare("SELECT * FROM members WHERE id=?");$st->execute([$id]);$member=$st->fetch();}
$plans=$pdo->query("SELECT * FROM plans ORDER BY price")->fetchAll();$pageTitle='Edit member';require "includes/header.php";
?><div class="page-intro"><div><h1>Edit member</h1><p>Update the profile details below.</p></div><a class="btn btn-secondary" href="members.php">← Back to members</a></div><section class="panel"><form method="post" class="form-grid" data-validate><div class="field"><label>Full name *</label><input name="name" value="<?= htmlspecialchars($member['name']) ?>" required minlength="2"></div><div class="field"><label>Email *</label><input name="email" type="email" value="<?= htmlspecialchars($member['email']) ?>" required></div><div class="field"><label>Phone *</label><input name="phone" value="<?= htmlspecialchars($member['phone']) ?>" pattern="[0-9]{10,15}" required></div><div class="field"><label>Gender</label><select name="gender"><?php foreach(['Prefer not to say','Female','Male','Other'] as $g): ?><option <?= $member['gender']===$g?'selected':'' ?>><?= $g ?></option><?php endforeach; ?></select></div><div class="field"><label>Join date</label><input type="date" name="join_date" value="<?= htmlspecialchars($member['join_date']) ?>" required></div><div class="field"><label>Membership plan</label><select name="plan_id"><option value="">No plan</option><?php foreach($plans as $p): ?><option value="<?= $p['id'] ?>" <?= (int)$member['plan_id']===(int)$p['id']?'selected':'' ?>><?= htmlspecialchars($p['name']) ?> — ₹<?= number_format($p['price']) ?></option><?php endforeach; ?></select></div><div class="field"><label>Status</label><select name="status"><option <?= $member['status']==='Active'?'selected':'' ?>>Active</option><option <?= $member['status']==='Inactive'?'selected':'' ?>>Inactive</option></select></div><div class="field field-action"><button class="btn btn-primary">Update member →</button></div></form></section><?php require "includes/footer.php"; ?>